"""
Metadata-Aware RAG system.

A Retrieval-Augmented Generation pipeline that:
  1. Extracts metadata filters (category, year, tags, source, ...) from a query.
  2. Retrieves candidate chunks from a vector store, optionally pre-filtered by
     those metadata filters.
  3. Ranks candidates by a weighted blend of semantic similarity and metadata
     relevance (filter match, priority, source_rank).
  4. Re-ranks with Maximal Marginal Relevance (MMR) for diversity.
  5. Generates a grounded answer from the top chunks (OpenAI LLM if
     OPENAI_API_KEY is set, otherwise a deterministic offline answerer).

The design is deliberately dependency-light on the hot path (chromadb + numpy
only) and fully configurable so it can be adapted to any domain.
"""

from __future__ import annotations

import hashlib
import os
import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

try:  # chromadb is the only hard dependency for retrieval
    import chromadb
except Exception as exc:  # pragma: no cover - defensive import error message
    raise ImportError(
        "chromadb is required. Install it with: pip install chromadb"
    ) from exc


# --------------------------------------------------------------------------- #
# Data model
# --------------------------------------------------------------------------- #
@dataclass
class Document:
    """A single retrievable unit: text plus its metadata."""

    id: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class Candidate:
    """A retrieved chunk with its scores."""

    id: str
    text: str
    metadata: Dict[str, Any]
    semantic_score: float  # raw cosine similarity, [0, 1]
    query: str
    combined_score: float = 0.0  # filled by MetadataRanker.rerank


@dataclass
class RAGResult:
    """The output of a RAG query."""

    query: str
    answer: str
    chunks: List[Candidate]
    filters: Dict[str, Any]


# --------------------------------------------------------------------------- #
# Embeddings (dependency-free fallback + pluggable interface)
# --------------------------------------------------------------------------- #
class Embedder:
    """Interface. Subclasses must implement ``embed``."""

    def embed(self, text: str) -> np.ndarray:  # pragma: no cover - interface
        raise NotImplementedError

    def embed_query(self, text: str) -> np.ndarray:
        return self.embed(text)


class HashEmbedder(Embedder):
    """
    Deterministic local embedder based on character n-gram hashing.

    No network access, no model download, identical vectors for identical
    inputs on every run. Good enough for demos, tests, and small corpora;
    swap it for OpenAIEmbeddings / SentenceTransformers in production.
    """

    def __init__(self, dim: int = 256, ngram_range: Tuple[int, int] = (2, 4)):
        self.dim = dim
        self.ngram_range = ngram_range

    def embed(self, text: str) -> np.ndarray:
        vec = np.zeros(self.dim, dtype=np.float32)
        for token in re.findall(r"[a-z0-9]+", text.lower()):
            for n in range(self.ngram_range[0], self.ngram_range[1] + 1):
                for i in range(len(token) - n + 1):
                    gram = token[i : i + n]
                    h = int(hashlib.md5(gram.encode("utf-8")).hexdigest(), 16)
                    vec[h % self.dim] += 1.0
        norm = float(np.linalg.norm(vec))
        if norm > 0:
            vec /= norm
        return vec


class OpenAIEmbedder(Embedder):
    """OpenAI text-embedding adapter (used when OPENAI_API_KEY is available)."""

    MODEL = "text-embedding-3-small"

    def __init__(self, model: str = MODEL):
        from langchain_openai import OpenAIEmbeddings

        self._embeddings = OpenAIEmbeddings(model=model)

    def embed(self, text: str) -> np.ndarray:
        return np.asarray(self._embeddings.embed_query(text), dtype=np.float32)


def default_embedder() -> Embedder:
    if os.environ.get("OPENAI_API_KEY"):
        try:
            return OpenAIEmbedder()
        except Exception:
            pass
    return HashEmbedder()


# --------------------------------------------------------------------------- #
# Metadata filter extraction from a natural-language query
# --------------------------------------------------------------------------- #
class MetadataExtractor:
    """
    Rule-based extraction of metadata filters from a query.

    Example:
        "Which security policy from 2024 covers password rules?"
        -> {"category": "policy", "year": 2024, "tags": ["security", "password"]}

    Extend by passing domain vocabularies (categories, tags, source names).
    """

    DEFAULT_CATEGORIES = [
        "policy",
        "guide",
        "faq",
        "playbook",
        "manual",
        "handbook",
        "checklist",
    ]
    DEFAULT_TAGS = [
        "security",
        "privacy",
        "incident",
        "password",
        "onboarding",
        "refund",
        "api",
        "compliance",
        "remote",
    ]

    def __init__(
        self,
        categories: Optional[Sequence[str]] = None,
        tags: Optional[Sequence[str]] = None,
        sources: Optional[Sequence[str]] = None,
    ):
        self.categories = list(categories or self.DEFAULT_CATEGORIES)
        self.tags = list(tags or self.DEFAULT_TAGS)
        self.sources = list(sources or [])

    def extract(self, query: str) -> Dict[str, Any]:
        q = query.lower().strip()
        if not q:
            return {}
        filters: Dict[str, Any] = {}

        # 1. Year
        m = re.search(r"\b(19|20)\d{2}\b", q)
        if m:
            filters["year"] = int(m.group(0))

        # 2. Category (match longest category first to avoid prefix collisions)
        for cat in sorted(self.categories, key=len, reverse=True):
            if cat in q:
                filters["category"] = cat
                break

        # 3. Tags
        found_tags = [t for t in self.tags if t in q]
        if found_tags:
            filters["tags"] = found_tags

        # 4. Source (explicit filename mention or "from <file>")
        for src in sorted(self.sources, key=len, reverse=True):
            if src.lower() in q:
                filters["source"] = src
                break
        else:
            m = re.search(r"\bfrom\s+([a-z0-9_.-]+)", q)
            if m and m.group(1) not in {"the", "a", "an", "our", "your"}:
                filters["source"] = m.group(1)

        # 5. Author ("by <name>")
        m = re.search(r"\bby\s+([a-z][a-z .'-]{2,})", q)
        if m:
            filters["author"] = m.group(1).strip()

        return filters


def build_where(filters: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """Translate a {field: value} dict into a chromadb ``where`` clause."""
    if not filters:
        return None
    clauses: List[Dict[str, Any]] = []
    for field, value in filters.items():
        if isinstance(value, (list, tuple, set)):
            values = list(value)
            if len(values) == 1:
                clauses.append({field: values[0]})
            else:
                clauses.append({field: {"$in": values}})
        else:
            clauses.append({field: value})
    if len(clauses) == 1:
        return clauses[0]
    return {"$and": clauses}


# --------------------------------------------------------------------------- #
# Vector store (chromadb-backed)
# --------------------------------------------------------------------------- #
class VectorStore:
    """Minimal chromadb wrapper with metadata-filtered similarity search."""

    def __init__(
        self,
        persist_dir: Optional[str] = None,
        collection_name: str = "metadata_rag",
        embedder: Optional[Embedder] = None,
    ):
        self.embedder = embedder or default_embedder()
        if persist_dir:
            Path(persist_dir).mkdir(parents=True, exist_ok=True)
            self._client = chromadb.PersistentClient(path=persist_dir)
        else:
            self._client = chromadb.EphemeralClient()
        self.collection = self._client.get_or_create_collection(
            name=collection_name,
            metadata={"hnsw:space": "cosine"},
        )

    # -- indexing ---------------------------------------------------------- #
    def add_documents(self, documents: Iterable[Document]) -> int:
        docs = list(documents)
        if not docs:
            return 0
        self.collection.upsert(
            ids=[d.id for d in docs],
            documents=[d.text for d in docs],
            metadatas=[dict(d.metadata) for d in docs],
            embeddings=[self.embedder.embed(d.text).tolist() for d in docs],
        )
        return len(docs)

    # -- retrieval --------------------------------------------------------- #
    def search(
        self,
        query: str,
        filters: Optional[Dict[str, Any]] = None,
        k: int = 10,
    ) -> List[Candidate]:
        where = build_where(filters)
        q = self.embedder.embed_query(query).tolist()
        result = self.collection.query(
            query_embeddings=[q],
            n_results=max(1, k),
            where=where,
            include=["documents", "metadatas", "distances"],
        )
        candidates: List[Candidate] = []
        # chromadb returns one nested result list per query; we sent one query.
        ids = result["ids"][0]
        docs = result["documents"][0]
        metas = result["metadatas"][0]
        dists = result["distances"][0]
        for i, cid in enumerate(ids):
            distance = float(dists[i])
            similarity = max(0.0, 1.0 - distance)  # cosine space: d = 1 - sim
            candidates.append(
                Candidate(
                    id=cid,
                    text=docs[i],
                    metadata=dict(metas[i] or {}),
                    semantic_score=similarity,
                    query=query,
                )
            )
        return candidates


# --------------------------------------------------------------------------- #
# Metadata-aware ranking
# --------------------------------------------------------------------------- #
def _value_matches(actual: Any, expected: Any) -> bool:
    """True if a metadata value matches a filter expectation."""
    if isinstance(expected, (list, tuple, set)):
        if isinstance(actual, list):
            return bool(set(actual) & set(expected))
        return actual in expected
    return actual == expected


class MetadataRanker:
    """
    Ranks candidates by blending normalized semantic similarity with a
    metadata relevance score.

    The metadata score rewards:
      * chunks whose metadata matches the query's inferred filters (50%),
      * chunks with a high declared ``priority`` (25%),
      * chunks with a high ``source_rank`` in [0, 1] (25%).

    All values are normalized to [0, 1]; the combination weights are exposed
    so users can tune them per domain.
    """

    def __init__(
        self,
        priority_map: Optional[Dict[str, float]] = None,
        semantic_weight: float = 0.6,
        metadata_weight: float = 0.4,
    ):
        self.priority_map = priority_map or {
            "high": 1.0,
            "medium": 0.6,
            "low": 0.3,
        }
        self.semantic_weight = semantic_weight
        self.metadata_weight = metadata_weight

    def metadata_score(
        self, metadata: Dict[str, Any], filters: Dict[str, Any]
    ) -> float:
        parts: List[float] = []
        if filters:
            matched = sum(
                1
                for field, expected in filters.items()
                if _value_matches(metadata.get(field), expected)
            )
            parts.append(0.5 * (matched / len(filters)))
        priority = self.priority_map.get(
            str(metadata.get("priority", "")).lower(), 0.0
        )
        parts.append(0.25 * priority)
        source_rank = metadata.get("source_rank")
        if isinstance(source_rank, (int, float)):
            parts.append(0.25 * max(0.0, min(1.0, float(source_rank))))
        return min(1.0, sum(parts)) if parts else 0.0

    def rerank(
        self,
        candidates: Sequence[Candidate],
        filters: Dict[str, Any],
    ) -> List[Candidate]:
        """Normalize semantic scores, blend with metadata score, sort desc."""
        if not candidates:
            return []
        sims = [c.semantic_score for c in candidates]
        lo, hi = min(sims), max(sims)
        span = (hi - lo) or 1.0
        for c in candidates:
            norm_semantic = (c.semantic_score - lo) / span
            meta = self.metadata_score(c.metadata, filters)
            c.combined_score = (
                self.semantic_weight * norm_semantic
                + self.metadata_weight * meta
            )
        return sorted(candidates, key=lambda c: c.combined_score, reverse=True)

    def mmr(
        self,
        ranked: Sequence[Candidate],
        k: int = 5,
        lambda_mult: float = 0.7,
        embedder: Optional[Embedder] = None,
    ) -> List[Candidate]:
        """
        Maximal Marginal Relevance: greedily pick items that are both relevant
        (high combined score) and dissimilar to already-picked items.
        """
        if not ranked:
            return []
        remaining = list(ranked)
        chosen: List[Candidate] = []
        vectors: Dict[str, np.ndarray] = {}
        if embedder is not None:
            vectors = {c.id: embedder.embed(c.text) for c in remaining}
        while len(chosen) < k and remaining:
            best_idx, best_value = 0, -1.0
            for i, cand in enumerate(remaining):
                relevance = cand.combined_score
                if chosen:
                    if vectors:
                        cand_vec = vectors[cand.id]
                        redundancy = max(
                            float(np.dot(cand_vec, vectors[o.id])) for o in chosen
                        )
                    else:
                        redundancy = max(
                            abs(cand.combined_score - o.combined_score) for o in chosen
                        )
                else:
                    redundancy = 0.0
                value = lambda_mult * relevance - (1.0 - lambda_mult) * redundancy
                if value > best_value:
                    best_value, best_idx = value, i
            chosen.append(remaining.pop(best_idx))
        return chosen


# --------------------------------------------------------------------------- #
# Answer generation
# --------------------------------------------------------------------------- #
SYSTEM_PROMPT = (
    "You are a precise assistant. Answer the user's question using ONLY the "
    "provided context. Cite your sources as [1], [2], etc. If the context does "
    "not contain enough information, say 'I don't have enough information.'"
)


def format_context(chunks: Sequence[Candidate], max_chars_per_chunk: int = 900) -> str:
    parts = []
    for i, c in enumerate(chunks, 1):
        src = c.metadata.get("source", "?")
        cat = c.metadata.get("category", "?")
        year = c.metadata.get("year", "?")
        snippet = c.text.strip()[:max_chars_per_chunk]
        parts.append(
            f"[{i}] (source={src}, category={cat}, year={year}, "
            f"score={c.combined_score:.3f})\n{snippet}"
        )
    return "\n\n".join(parts)


class Answerer:
    """Interface: produce an answer given a question and retrieved chunks."""

    def answer(self, question: str, chunks: Sequence[Candidate]) -> str:
        raise NotImplementedError  # pragma: no cover - interface


class TemplateAnswerer(Answerer):
    """
    Deterministic offline answerer. No LLM / network needed.

    Returns the most informative sentence of the top-ranked chunk plus a
    listing of the retrieved sources. Swap for OpenAIAnswerer in production.
    """

    def answer(self, question: str, chunks: Sequence[Candidate]) -> str:
        if not chunks:
            return "I don't have enough information."
        top = chunks[0]
        sentences = [
            s.strip()
            for s in re.split(r"(?<=[.!?])\s+", top.text)
            if len(s.strip()) > 20
        ]
        lead = sentences[0] if sentences else top.text.strip()[:300]
        sources = ", ".join(
            sorted({c.metadata.get("source", "?") for c in chunks})
        )
        return (
            f"Grounded answer (offline mode):\n{lead}\n\n"
            f"Sources: {sources}"
        )


class OpenAIAnswerer(Answerer):
    """LLM answerer used when OPENAI_API_KEY is set."""

    def __init__(self, model: str = "gpt-4o-mini", temperature: float = 0.0):
        from langchain_openai import ChatOpenAI

        self._llm = ChatOpenAI(model=model, temperature=temperature)

    def answer(self, question: str, chunks: Sequence[Candidate]) -> str:
        from langchain_core.messages import HumanMessage, SystemMessage

        context = format_context(chunks)
        messages = [
            SystemMessage(content=SYSTEM_PROMPT),
            HumanMessage(
                content=f"Context:\n{context}\n\nQuestion: {question}"
            ),
        ]
        return self._llm.invoke(messages).content


def default_answerer() -> Answerer:
    if os.environ.get("OPENAI_API_KEY"):
        try:
            return OpenAIAnswerer()
        except Exception:
            pass
    return TemplateAnswerer()


# --------------------------------------------------------------------------- #
# Chunking & document loading (front matter = metadata)
# --------------------------------------------------------------------------- #
def chunk_text(
    text: str, chunk_size: int = 600, overlap: int = 120
) -> List[str]:
    """Split text into overlapping chunks; returns [text] if it already fits."""
    text = text.strip()
    if not text:
        return []
    if len(text) <= chunk_size:
        return [text]
    chunks: List[str] = []
    start = 0
    while start < len(text):
        end = min(start + chunk_size, len(text))
        chunks.append(text[start:end])
        if end == len(text):
            break
        start = max(end - overlap, start + 1)
    return chunks


def _parse_scalar(value: str) -> Any:
    value = value.strip()
    if value.startswith("[") and value.endswith("]"):
        inner = value[1:-1]
        return [
            _parse_scalar(item)
            for item in re.split(r",\s*", inner)
            if item.strip()
        ]
    if re.fullmatch(r"-?\d+", value):
        return int(value)
    if re.fullmatch(r"-?\d+\.\d+", value):
        return float(value)
    if value.lower() in {"true", "yes"}:
        return True
    if value.lower() in {"false", "no"}:
        return False
    return value.strip("\"' ")


def parse_front_matter(text: str) -> Tuple[Dict[str, Any], str]:
    """
    Parse optional YAML-ish front matter (---\nkey: value\n---) at the top of a
    document. Returns (metadata, body_without_front_matter).
    """
    match = re.match(r"^---\s*\n(.*?)\n---\s*\n?", text, re.DOTALL)
    if not match:
        return {}, text
    metadata: Dict[str, Any] = {}
    for line in match.group(1).splitlines():
        if ":" not in line or line.strip().startswith("#"):
            continue
        key, value = line.split(":", 1)
        key = key.strip()
        parsed = _parse_scalar(value)
        if key and parsed is not None and parsed != "":
            metadata[key] = parsed
    return metadata, text[match.end() :]


def _default_source_rank(metadata: Dict[str, Any]) -> float:
    if isinstance(metadata.get("source_rank"), (int, float)):
        return float(metadata["source_rank"])
    priority = str(metadata.get("priority", "")).lower()
    return {"high": 0.9, "medium": 0.6, "low": 0.3}.get(priority, 0.5)


def load_documents(
    folder: str | Path,
    chunk_size: int = 600,
    chunk_overlap: int = 120,
) -> List[Document]:
    """Load *.md/*.txt/*.rst files with front matter, chunk them, tag metadata."""
    root = Path(folder)
    documents: List[Document] = []
    for path in sorted(root.rglob("*")):
        if path.suffix.lower() not in {".md", ".txt", ".rst"}:
            continue
        raw = path.read_text(encoding="utf-8", errors="ignore")
        metadata, body = parse_front_matter(raw)
        metadata.setdefault("source", path.name)
        metadata["source_rank"] = _default_source_rank(metadata)
        for i, chunk in enumerate(chunk_text(body, chunk_size, chunk_overlap)):
            if not chunk.strip():
                continue
            documents.append(
                Document(
                    id=f"{path.stem}::{i}",
                    text=chunk.strip(),
                    metadata={**metadata},
                )
            )
    return documents


# --------------------------------------------------------------------------- #
# Top-level RAG facade
# --------------------------------------------------------------------------- #
class MetadataRAG:
    """
    Retrieval-Augmented Generation with metadata filtering and ranking.

    Usage:
        store = VectorStore(persist_dir="chroma_db")
        rag = MetadataRAG(store=store)
        result = rag.answer("Which security policy from 2024 covers passwords?")
        print(result.answer)
        for chunk in result.chunks:
            print(chunk.metadata.get("source"), round(chunk.combined_score, 3))
    """

    def __init__(
        self,
        store: VectorStore,
        extractor: Optional[MetadataExtractor] = None,
        ranker: Optional[MetadataRanker] = None,
        answerer: Optional[Answerer] = None,
        k: int = 5,
        use_mmr: bool = True,
        mmr_lambda: float = 0.7,
    ):
        self.store = store
        self.extractor = extractor or MetadataExtractor(sources=[])
        self.ranker = ranker or MetadataRanker()
        self.answerer = answerer or default_answerer()
        self.k = k
        self.use_mmr = use_mmr
        self.mmr_lambda = mmr_lambda
        self.last_filters: Dict[str, Any] = {}

    # -- retrieval --------------------------------------------------------- #
    def retrieve(self, query: str, k: Optional[int] = None) -> List[Candidate]:
        k = k or self.k
        self.last_filters = self.extractor.extract(query)
        # Fetch more candidates than needed so ranking has room to work.
        candidates = self.store.search(query, self.last_filters, k=k * 3)
        ranked = self.ranker.rerank(candidates, self.last_filters)
        if self.use_mmr:
            return self.ranker.mmr(ranked, k=k, lambda_mult=self.mmr_lambda,
                                   embedder=self.store.embedder)
        return ranked[:k]

    # -- generation -------------------------------------------------------- #
    def answer(self, query: str, k: Optional[int] = None) -> RAGResult:
        chunks = self.retrieve(query, k=k)
        answer = self.answerer.answer(query, chunks)
        return RAGResult(
            query=query,
            answer=answer,
            chunks=chunks,
            filters=dict(self.last_filters),
        )
